    58	function Avatar({
    59	    source: originalSource,
    60	    imageStyles,
    61	    iconAdditionalStyles,
    62	    containerStyles,
    63	    size = CONST.AVATAR_SIZE.DEFAULT,
    64	    fill,
    65	    fallbackIcon = Expensicons.FallbackAvatar,
    66	    fallbackIconTestID = '',
    67	    type,
    68	    name = '',
    69	    avatarID,
    70	}: AvatarProps) {
    71	    const theme = useTheme();
    72	    const styles = useThemeStyles();
    73	    const StyleUtils = useStyleUtils();
    74	    const [imageError, setImageError] = useState(false);
    75	
    76	    useNetwork({onReconnect: () => setImageError(false)});
    77	
    78	    useEffect(() => {
    79	        setImageError(false);
