    83	    const userAccountID = isWorkspace ? undefined : (avatarID as number);
    84	
    85	    const source = isWorkspace ? originalSource : getAvatar(originalSource, userAccountID);
    86	    const useFallBackAvatar = imageError || !source || source === Expensicons.FallbackAvatar;
    87	    const fallbackAvatar = isWorkspace ? getDefaultWorkspaceAvatar(name) : fallbackIcon || Expensicons.FallbackAvatar;
    88	    const fallbackAvatarTestID = isWorkspace ? getDefaultWorkspaceAvatarTestID(name) : fallbackIconTestID || 'SvgFallbackAvatar Icon';
    89	    const avatarSource = useFallBackAvatar ? fallbackAvatar : source;
    90	
    91	    // We pass the color styles down to the SVG for the workspace and fallback avatar.
    92	    const iconSize = StyleUtils.getAvatarSize(size);
    93	    const imageStyle: StyleProp<ImageStyle> = [StyleUtils.getAvatarStyle(size), imageStyles, styles.noBorderRadius];
    94	    const iconStyle = imageStyles ? [StyleUtils.getAvatarStyle(size), styles.bgTransparent, imageStyles] : undefined;
    95	
    96	    let iconColors;
    97	    if (isWorkspace) {
    98	        iconColors = StyleUtils.getDefaultWorkspaceAvatarColor(avatarID?.toString() ?? '');
    99	    } else if (useFallBackAvatar) {
   100	        iconColors = StyleUtils.getBackgroundColorAndFill(theme.buttonHoveredBG, theme.icon);
   101	    } else {
   102	        iconColors = null;
   103	    }
   104	
   105	    return (
   106	        <View style={[containerStyles, styles.pointerEventsNone]}>
   107	            {typeof avatarSource === 'string' ? (
   108	                <View style={[iconStyle, StyleUtils.getAvatarBorderStyle(size, type), iconAdditionalStyles]}>
   109	                    <Image
   110	                        source={{uri: avatarSource}}
   111	                        style={imageStyle}
   112	                        onError={() => setImageError(true)}
   113	                        cachePolicy="memory-disk"
   114	                    />
   115	                </View>
   116	            ) : (
   117	                <View style={iconStyle}>
   118	                    <Icon
   119	                        testID={fallbackAvatarTestID}
   120	                        src={avatarSource}
   121	                        height={iconSize}
   122	                        width={iconSize}
   123	                        fill={imageError ? (iconColors?.fill ?? theme.offline) : (iconColors?.fill ?? fill)}
   124	                        additionalStyles={[StyleUtils.getAvatarBorderStyle(size, type), iconColors, iconAdditionalStyles]}
   125	                    />
   126	                </View>
   127	            )}
   128	        </View>
   129	    );
   130	}
